#include "heartbeat.hpp"

void Heartbeat::on_receive() {
    seen_ = true;
}

bool Heartbeat::on_interval_end() {
    misses_ = seen_ ? 0 : misses_ + 1;
    seen_ = false;
    offline_ = misses_ > kMaxMisses;
    return offline_;
}

